const body = $input.first().json.body;

const required = ['sender_name', 'sender_company', 'sender_value_prop', 'target_role', 'target_industry'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

const tones = ['direct', 'warm', 'formal', 'casual', 'challenger'];
const tone = tones.includes(body.tone) ? body.tone : 'direct';

return [{
  json: {
    valid: true,
    senderName: body.sender_name.trim(),
    senderCompany: body.sender_company.trim(),
    senderRole: body.sender_role || '',
    senderValueProp: body.sender_value_prop.trim().slice(0, 600),
    targetRole: body.target_role.trim(),
    targetIndustry: body.target_industry.trim(),
    targetPainPoints: (body.target_pain_points || '').slice(0, 400),
    specificProspect: body.specific_prospect || null,
    specificCompany: body.specific_company || null,
    tone,
    sequenceLength: Math.min(5, Math.max(2, parseInt(body.sequence_length) || 3)),
    channelOrder: Array.isArray(body.channel_order)
      ? body.channel_order
      : ['email', 'email', 'linkedin', 'email'],
    socialProof: (body.social_proof || '').slice(0, 300),
    callToAction: body.call_to_action || '15-minute call',
    replyEmail: body.reply_email || null,
    requestedAt: new Date().toISOString()
  }
}];

values.content:
Write a cold outreach sequence.

Sender: {{ $json.senderName }}{{ $json.senderRole ? ', ' + $json.senderRole : '' }} at {{ $json.senderCompany }}
Value proposition: {{ $json.senderValueProp }}
Social proof: {{ $json.socialProof || 'none provided' }}

Target: {{ $json.targetRole }} in {{ $json.targetIndustry }}
{{ $json.specificProspect ? 'Specific prospect name: ' + $json.specificProspect : 'Generic — write for the archetype, not a specific person' }}
{{ $json.specificCompany ? 'Specific company: ' + $json.specificCompany : '' }}
Known pain points: {{ $json.targetPainPoints || 'infer from role and industry' }}

Tone: {{ $json.tone }}
Sequence length: {{ $json.sequenceLength }} touchpoints
Channel order: {{ $json.channelOrder.slice(0, $json.sequenceLength).join(' → ') }}
Desired CTA: {{ $json.callToAction }}

Write the full sequence as this JSON:
{
  "sequence_overview": "one sentence on the overall strategy and angle for this sequence",
  "touchpoints": [
    {
      "step": 1,
      "channel": "email or linkedin",
      "send_timing": "Day 1 / Day 5 / etc.",
      "subject_line": "email subject line — null for linkedin",
      "message": "the full message body — no placeholders like [NAME], use the actual prospect name or role if not personalized. Keep emails under 100 words. LinkedIn notes under 300 chars. Follow-ups under 80 words.",
      "purpose": "what this touchpoint is trying to accomplish",
      "writing_notes": "what makes this message work — why this angle, why this length"
    }
  ],
  "personalization_hooks": ["3-5 specific things to research about each prospect before sending — what to look for and where"],
  "objection_responses": [
    {
      "objection": "common objection for this type of outreach",
      "response": "how to respond in 2-3 sentences"
    }
  ],
  "what_not_to_do": ["2-3 common mistakes for this specific sender/target combination"]
}

