const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let sequence;
try {
  sequence = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const input = $('Validate Input').first().json;
sequence._meta = {
  senderName: input.senderName,
  senderCompany: input.senderCompany,
  targetRole: input.targetRole,
  targetIndustry: input.targetIndustry,
  tone: input.tone,
  replyEmail: input.replyEmail
};
return [{ json: sequence }];
